import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    book = {}  # id -> [side, price, qty, seq, active]
    seq_counter = [0]

    def next_seq():
        seq_counter[0] += 1
        return seq_counter[0]

    def clean_buy():
        while buy_heap:
            negp, s, oid = buy_heap[0]
            o = book.get(oid)
            if o is None or not o[4] or o[2] <= 0:
                heapq.heappop(buy_heap)
            else:
                break

    def clean_sell():
        while sell_heap:
            p, s, oid = sell_heap[0]
            o = book.get(oid)
            if o is None or not o[4] or o[2] <= 0:
                heapq.heappop(sell_heap)
            else:
                break

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            o = book.get(oid)
            if o is not None and o[4] and o[2] > 0:
                o[4] = False
            continue

        if typ in ('limit', 'ioc'):
            _, oid, side, price, qty = order
        else:  # market
            _, oid, side, qty = order
            price = None

        remaining = qty
        seq = next_seq()

        if side == 'buy':
            # match against sell_heap
            while remaining > 0:
                clean_sell()
                if not sell_heap:
                    break
                top_price, top_seq, top_id = sell_heap[0]
                if typ != 'market' and price is not None and top_price > price:
                    break
                sell_order = book[top_id]
                trade_qty = min(remaining, sell_order[2])
                trade_price = sell_order[1]
                trades.append([oid, top_id, trade_price, trade_qty])
                remaining -= trade_qty
                sell_order[2] -= trade_qty
                if sell_order[2] <= 0:
                    heapq.heappop(sell_heap)
            if typ == 'limit' and remaining > 0:
                book[oid] = ['buy', price, remaining, seq, True]
                heapq.heappush(buy_heap, (-price, seq, oid))
            else:
                if remaining > 0:
                    # discard remainder, but still record order if not already
                    pass
                # ensure not left resting; nothing to do for ioc/market
        else:  # sell
            while remaining > 0:
                clean_buy()
                if not buy_heap:
                    break
                negp, top_seq, top_id = buy_heap[0]
                top_price = -negp
                if typ != 'market' and price is not None and top_price < price:
                    break
                buy_order = book[top_id]
                trade_qty = min(remaining, buy_order[2])
                trade_price = buy_order[1]
                trades.append([top_id, oid, trade_price, trade_qty])
                remaining -= trade_qty
                buy_order[2] -= trade_qty
                if buy_order[2] <= 0:
                    heapq.heappop(buy_heap)
            if typ == 'limit' and remaining > 0:
                book[oid] = ['sell', price, remaining, seq, True]
                heapq.heappush(sell_heap, (price, seq, oid))

    return trades

